import java.io.*; import java.net.*; import java.text.NumberFormat; import java.util.Locale;
public class RPCServer { public static void main(String[] a)throws Exception{try(ServerSocket ss=new ServerSocket(7000)){System.out.println("PAYMESH TCP-RPC SERVER | port=7000");while(true){Socket s=ss.accept();new Thread(()->handle(s)).start();}}} static void handle(Socket s){try(s){BufferedReader in=new BufferedReader(new InputStreamReader(s.getInputStream()));PrintWriter out=new PrintWriter(s.getOutputStream(),true);String[] x=in.readLine().split("\\|");String method=x[2].toUpperCase();String p=method.equals("CARD")?"Card-Processor":method.equals("NETBANKING")?"Banking-Processor":"UPI-Processor";out.println("SUCCESS | Order="+x[0]+" | Amount=₹"+NumberFormat.getNumberInstance(new Locale("en","IN")).format(Double.parseDouble(x[1]))+" | Method="+method+" | Processor="+p);}catch(Exception e){e.printStackTrace();}}}
